public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }

    int hash = 1;
    for (long element : array) {
        long value = element;
        if (value == Long.MIN_VALUE) {
            value = Long.MAX_VALUE;
        }
        hash = 31 * hash + Long.hashCode(value);
    }

    return hash;
}

