private TreeNode<T> rotateRight(TreeNode<T> node) {
	if (node == null) {
		throw new IllegalArgumentException("Node cannot be null");
	}

	TreeNode<T> parent = node.parent;
	TreeNode<T> leftChild = node.left;
	TreeNode<T> rightChild = node.right;

	// make rightChild the new parent of {@code node}
	if (rightChild != null) {
		rightChild.parent = node;
	}

	// make node a left child of its new parent
	node.parent = rightChild;
	node.right = rightChild;

	// make node a right child of its left child
	if (leftChild != null) {
		leftChild.parent = node;
		leftChild.right = node;
	}

	// make the new parent of {@code node} the right child of its current parent
	if (parent != null) {
		parent.right = node;
	}

	return parent;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> temp = node.right;
    node.right = temp.left;
    temp.left = node;
    node = temp;
    return node;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> parent = node.getParent();
    TreeNode<T> grandparent = parent.getParent();

    if (grandparent == null) { // node is actually the root node
        return node;
    }

    TreeNode<T> sibling = node.getSibling();
    TreeNode<T> newParent = sibling.setChild(node.getChild());
    newParent.setParent(grandparent);
    grandparent.setChild(newParent);

    node.setParent(newParent);
    return node;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> newParent = node.left;
    node.left = newParent.right;
    newParent.right = node;
    return newParent;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Create a new node to be the parent of the given node
    TreeNode<T> parent = new TreeNode<T>(node.getValue());

    // Update the parent's right child to be the given node
    parent.setRightChild(node);

    // Set the given node's parent to be the new parent
    node.setParent(parent);

    // Update the parent's left child to be the given node's left child
    parent.setLeftChild(node.getLeftChild());

    // Update the given node's left child to be null
    node.setLeftChild(null);

    // Set the new parent's left child's parent to be the new parent
    if (parent.getLeftChild() != null) {
        parent.getLeftChild().setParent(parent);
    }

    return parent;
}

