public static void addToClassPath(Vector<URL> cpV, String dir) {
    try {
        File dirFile = new File(dir);
        if (!dirFile.isDirectory()) {
            throw new IllegalArgumentException("Input 'dir' is not a directory.");
        }
        for (File file : dirFile.listFiles()) {
            if (file.isFile() && file.getName().endsWith(".jar")) {
                cpV.add(file.toURI().toURL());
            }
        }
    } catch (MalformedURLException ex) {
        throw new IllegalArgumentException("Error adding file to classpath: " + ex.getMessage());
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    // Check if the dir exists and is a directory
    if (dir == null || !Files.isDirectory(Paths.get(dir))) {
        throw new IllegalArgumentException("Invalid directory path: " + dir);
    }

    // Get all the jar files in the directory
    Vector<String> jarFiles = new Vector<>();
    try (Stream<Path> filesInDirectory = Files.list(Paths.get(dir))) {
        for (Path file : filesInDirectory.collect(Collectors.toList())) {
            String fileName = file.getFileName().toString();
            if (fileName.endsWith(".jar") && Files.isRegularFile(file)) {
                jarFiles.add(fileName);
            }
        }
    } catch (IOException e) {
        throw new IllegalArgumentException("Error listing files in directory: " + dir, e);
    }

    // Add the jar files to the classpath
    for (String jarFile : jarFiles) {
        URL jarUrl = Paths.get(dir, jarFile).toUri().toURL();
        cpV.add(jarUrl);
    }
}

