  int endIndex = startIndex;
  while (headers.charAt(endIndex) != '\r') {
    endIndex++;
  }
  endIndex++;
  return endIndex;
}

private int parseEndOfLine(String headerPart,int end) {

    // Iterate through the headerPart from the end index until a \r\n sequence is found
    for (int i = end - 1; i >= 0; i--) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }

    // Return -1 if no \r\n sequence is found
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    int lastLF = -1;
    for (int i = end; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\r' && (i == headerPart.length() - 1 || headerPart.charAt(i + 1) == '\n')) {
            lastLF = i;
            break;
        }
    }
    return lastLF;
}

private int parseEndOfLine(String headerPart, int end) {
    //Variable to store the index of the \r\n sequence.
    int bytesRead = 0;

    //A flag to indicate whether the end of line has been found.
    boolean foundEnd = false;

    while(!foundEnd){
        if(end + bytesRead >= headerPart.length()){
            //The end of the line has been reached.
            foundEnd = true;
        } else if(headerPart.charAt(end + bytesRead) == '\r' && headerPart.charAt(end + bytesRead + 1) == '\n'){
            //The end of the line has been found.
            foundEnd = true;
        } else {
            //The byte is not part of the end of line.
            bytesRead++;
        }
    }

    return end + bytesRead;
}

private int parseEndOfLine(String headerPart, int end) {
    int i = end;
    while (i < headerPart.length() && headerPart.charAt(i) != '\r' && headerPart.charAt(i) != '\n') {
        i++;
    }
    return i;
}

