                // Add the edge to the right vertices set
                rightVertices.add(edge);
            }
        }
    }

    // For each vertex in the left vertices set
    for (V vertex : leftVertices) {
        // For each vertex in the right vertices set
        for (V neighbor : rightVertices) {
