public static int writeDelimitedTo(OutputStream out, Object message, Schema<Object> schema, LinkedBuffer buffer) throws IOException {
    int size = 0;
    // Get the byte array representation of the message
    byte[] bytes = schema.toByteArray(message);
    // Write the size of the message to the output stream
    size += buffer.writeVarint32(out, bytes.length);
    // Write the message to the output stream
    size += buffer.writeRawBytes(out, bytes);
    return size;
}

public static int writeDelimitedTo(OutputStream out, Object message, Schema schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    ByteString bytes = schema.toByteString(message, buffer);
    int size = bytes.size();
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out, size);
    codedOut.writeInt32NoTag(size);
    codedOut.writeRawBytes(bytes);
    codedOut.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    byte[] bytes = schema.toByteArray(message, buffer);

    ByteBuffer byteBuffer = ByteBuffer.wrap(bytes);
    byteBuffer.putVarint32(size);

    out.write(byteBuffer.array(), 0, size + Varint.varint32Length(size));

    return size;
}

