public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {

    // Check if the generic type is parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the parameterized type
    ParameterizedType parameterizedType = (ParameterizedType) genericType;

    // Get the type variable
    TypeVariable<?>[] typeVariables = parameterizedType.getActualTypeArguments();

    // Check if the type variables are assignable to the target type
    if (!typeVariablesAssignableToTargetType(typeVariables, targetType)) {
        return null;
    }

    // Resolve the type variables
    Class<?>[] typeArguments = resolveTypeArguments(typeVariables, targetType);

    return typeArguments;
}

private static boolean typeVariablesAssignableToTargetType(TypeVariable<?>[] typeVariables, Class<?> targetType) {
    for (TypeVariable<?> typeVariable : typeVariables) {
        if (!typeVariable.getBounds().get(0).equals(targetType)) {
            return false;
        }
    }
    return true;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType && targetType.getGenericSuperclass() instanceof ParameterizedType) {
      ParameterizedType parametricType = (ParameterizedType) genericType;
      ParameterizedType targetParametricType = (ParameterizedType) targetType.getGenericSuperclass();
      if (parametricType.getActualTypeArguments().length == targetParametricType.getActualTypeArguments().length) {
        return resolveTypeArguments(parametricType.getActualTypeArguments(), targetParametricType.getActualTypeArguments());
      }
    }
    return null;
  }

private static Class<?>[] resolveTypeArguments(Type[] genericTypes, Type[] targetTypes) {
    if (genericTypes.length == 0 || targetTypes.length == 0) {
      return new Class<?>[0];
    }

    Class<?>[] resolvedTypes = new Class<?>[genericTypes.length];
    for (int i = 0; i < resolvedTypes.length; i++) {
      resolvedTypes[i] = resolveType(genericTypes[i], targetTypes[i]);
    }
    return resolvedTypes;
  }

private static Class<?> resolveType(Type genericType, Type targetType) {
    if (genericType instanceof Class) {
      return (Class<?>) genericType;
    } else if (genericType instanceof ParameterizedType) {
      ParameterizedType parametricType = (ParameterizedType) genericType;
      Type[] actualTypeArgs = parametricType.getActualTypeArguments();
      if (actualTypeArgs.length == 1 && actualTypeArgs[0].equals(targetType)) {
        return (Class<?>) parametricType.getRawType();
      }
    }
    return null;
  }

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
	// check if genericType is not parameterized and return null in that case
	if (genericType instanceof ParameterizedType) {
		ParameterizedType ptype = (ParameterizedType) genericType;
		Type[] typeArguments = ptype.getActualTypeArguments();
		Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
		for (int i = 0; i < typeArguments.length; i++) {
			Type typeArgument = typeArguments[i];
			if (typeArgument instanceof TypeVariable) {
				String typeVarName = ((TypeVariable) typeArgument).getName();
				TypeVariable[] typeParams = targetType.getTypeParameters();
				for (TypeVariable typeParam : typeParams) {
					if (typeVarName.equals(typeParam.getName())) {
						resolvedArguments[i] = (Class<?>) typeParam.getGenericDeclaration();
					}
				}
			} else {
				resolvedArguments[i] = (Class<?>) typeArgument;
			}
		}
		return resolvedArguments;
	} else {
		return null;
	}
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Step 1: Check if the generic type is parameterized
    if (!(genericType instanceof ParameterizedType)) {
      return null;
    }

    // Step 2: Cast the generic type to ParameterizedType
    ParameterizedType parameterizedType = (ParameterizedType) genericType;

    // Step 3: Get the type variables of the target type
    TypeVariable<?>[] typeVariables = targetType.getTypeParameters();

    // Step 4: Create a map of type variables to their actual types
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    for (int i = 0; i < typeVariables.length; i++) {
      TypeVariable<?> typeVariable = typeVariables[i];
      Type actualType = typeVariable.getBounds()[0];
      typeVariableMap.put(typeVariable, actualType);
    }

    // Step 5: Get the actual types from the type variable map
    Type[] actualTypes = Arrays.stream(parameterizedType.getActualTypeArguments())
        .map(typeVariable -> typeVariableMap.getOrDefault(typeVariable, typeVariable))
        .toArray(Type[]::new);

    // Step 6: Return the actual types
    return actualTypes;
  }

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
        for (int i = 0; i < actualTypeArguments.length; i++) {
            if (actualTypeArguments[i] instanceof Class) {
                resolvedArguments[i] = (Class<?>) actualTypeArguments[i];
            } else if (actualTypeArguments[i] instanceof TypeVariable) {
                TypeVariable<?> typeVariable = (TypeVariable<?>) actualTypeArguments[i];
                resolvedArguments[i] = resolveArgument(typeVariable, targetType);
            } else {
                throw new IllegalArgumentException("Unsupported type: " + actualTypeArguments[i]);
            }
        }
        return resolvedArguments;
    } else {
        return null;
    }
}

public static Class<?> resolveArgument(TypeVariable<?> typeVariable, Class<?> targetType) {
    GenericDeclaration genericDeclaration = typeVariable.getGenericDeclaration();
    if (genericDeclaration instanceof Class) {
        Class<?> declaringClass = (Class<?>) genericDeclaration;
        Type superClass = targetType.getSuperclass();
        if (declaringClass.isAssignableFrom(superClass)) {
            return resolveArgument((Class<?>) superClass, typeVariable.getName());
        }
        for (Type genericInterface : targetType.getGenericInterfaces()) {
            if (declaringClass.isAssignableFrom(genericInterface)) {
                return resolveArgument((Class<?>) genericInterface, typeVariable.getName());
            }
        }
    }
    return null;
}

