        throw new IllegalArgumentException("tableName and mappings cannot be null");
    }

    // retrieve history mapping from current index
    Mappings historyMapping = getHistoryMapping(tableName);

    // iterate through current mappings to check for field existence
    Mappings differences = new Mappings();
    for (Map.Entry<String, Mapping> entry : mappings.entrySet()) {
        String fieldName = entry.getKey();
        if (!historyMapping.containsKey(fieldName)) {
            differences.put(fieldName, entry.getValue());
        }
    }

    // return mappings without _source config to avoid conflicts
    Mappings finalMappings = new Mappings();
    for (Map.Entry<String, Mapping> entry : differences.entrySet()) {
        finalMappings.put(entry.getKey(), entry.getValue());
    }
    return finalMappings;
}

