static long compressTimeBucket(long timeBucket, int dayStep) {
    long compressedTimeBucket = timeBucket - (timeBucket % dayStep);
    return compressedTimeBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    // Check if dayStep is valid
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Invalid dayStep: " + dayStep);
    }

    // Check if timeBucket is valid
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("Invalid timeBucket: " + timeBucket);
    }

    // Calculate the re-formatted time bucket
    int timeBucketYear = timeBucket / 1000000;
    int timeBucketMonth = (timeBucket - timeBucketYear * 1000000) / 100;
    int timeBucketDay = timeBucket - timeBucketYear * 1000000 - timeBucketMonth * 100;
    int reFormattedDay = (timeBucketDay + 1) / dayStep * dayStep;
    long reFormattedTimeBucket = timeBucketYear * 1000000 + timeBucketMonth * 100 + reFormattedDay;

    return reFormattedTimeBucket;
}

public static Long compressTimeBucket(Long timeBucket, Integer dayStep) {
  if (timeBucket == null || dayStep == null) {
    throw new IllegalArgumentException("timeBucket and dayStep must both be non-null");
  }
  if (dayStep == 0) {
    throw new IllegalArgumentException("dayStep must be positive");
  }
  if (dayStep < 0) {
    throw new IllegalArgumentException("dayStep must be positive");
  }
  final int year = (int) (timeBucket / (365 * 24));
  final int month = (int) (timeBucket % (365 * 24) / 30);
  final int day = (int) (timeBucket % (365 * 24) % 30);
  final int dayMod = day - 1;
  final int monthMod = month - 1;
  final int yearMod = year - 1;
  final int newDay = dayMod % dayStep + 1;
  final int newMonth = monthMod % monthStep + 1;
  final int newYear = yearMod % yearStep + 1;
  return (long) (newYear * (365 * 24) + newMonth * 30 + newDay);
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long compressedTimeBucket = timeBucket;

    // Check if the day step is valid
    if (dayStep > 0 && dayStep <= 31) {
      int day = (int) (timeBucket % 100);
      compressedTimeBucket = timeBucket - day;
      compressedTimeBucket += dayStep;
    } else {
      throw new IllegalArgumentException("Invalid day step value: " + dayStep);
    }

    return compressedTimeBucket;
  }

static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the base time bucket value
    long baseTimeBucket = timeBucket / dayStep;

    // Calculate the remainder value
    long remainder = timeBucket % dayStep;

    // If the remainder is non-zero, subtract it from the base value
    if (remainder != 0) {
        baseTimeBucket -= remainder;
    }

    // Return the compressed time bucket value
    return baseTimeBucket;
}

private static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(index + i);
        if (c >= 0x0001 && c <= 0x007F) {
            size++;
        } else if (c >= 0x0080 && c <= 0x07FF) {
            size += 2;
        } else if (c >= 0x0800 && c <= 0xFFFF) {
            size += 3;
        } else if (Character.isHighSurrogate(c)) {
            size += 4;
        }
    }
    return size;
}

int length = Math.min(len, str.length() - index);
  byte[] bytes = new byte[length];
  for (int i = 0; i < length; i++) {
    char c = str.charAt(index + i);
    if (c >= 0 && c <= 0x7F) {
      bytes[i] = (byte) c;
    } else if (c >= 0x80 && c <= 0x7FF) {
      bytes[i] = (byte) ((c >> 6) | 0xC0);
      bytes[++i] = (byte) ((c & 0x3F) | 0x80);
    } else {
      bytes[i] = (byte) ((c >> 12) | 0xE0);
      bytes[++i] = (byte) (((c >> 6) & 0x3F) | 0x80);
      bytes[++i] = (byte) ((c & 0x3F) | 0x80);
    }
  }

  int utf8Size = 0;
  for (byte b : bytes) {
    if ((b & 0xFF) >= 0xC0) {
      utf8Size++;
    }
  }
  return utf8Size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int length) {
      int utf8Size = 0;
      for (int i = index; i < index + length; i++) {
            int codePoint = str.codePointAt(i);
            if (codePoint < 0x80) {
                  utf8Size++;
            } else if (codePoint <= 0x7FF) {
                  utf8Size += 2;
            } else if (codePoint <= 0xFFFF) {
                  utf8Size += 3;
            } else if (codePoint <= 0x10FFFF) {
                  utf8Size += 4;
            }
      }
      return utf8Size;
}

