        for (int i = 0; i < byteLength; i++) {
            add(0);
        }
        return this;
    }

    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        // If the byte offset is invalid, throw an exception
        throw new IllegalArgumentException("Invalid byte offset");
    }

    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        // If the byte length is invalid, throw an exception
        throw new IllegalArgumentException("Invalid byte length");
    }

    // Copy the specified bytes from the byte array into this byte vector
    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
        add(byteArrayValue[i]);
    }

    return this;
}

