public void removeFromTreeEdgeList() {
    if (head != null && prev != null) {
        // Remove this edge from the head doubly linked list
        head.next = this.next;
        if (this.next != null) {
            this.next.prev = head;
        }
        // Remove this edge from the prev doubly linked list
        prev.next = this.next;
        if (this.next != null) {
            this.next.prev = prev;
        }
    } else {
        // One or both of head and prev are null, which means this edge is not
        // part of either doubly linked list.
        throw new IllegalStateException("Edge is not part of any doubly linked list");
    }
}

