        List<DoublyLinkedList<TreeEdge>> treeEdgeLists = new ArrayList<>();
        for (Map.Entry<TreeNode, List<DoublyLinkedList<TreeEdge>>> entry : treeEdgeLists.entrySet()) {
            List<DoublyLinkedList<TreeEdge>> lists = entry.getValue();
            for (DoublyLinkedList<TreeEdge> list : lists) {
                if (list.head == this) {
                    // If the edge is the head of the list, remove it
                    list.removeHead();
                } else if (list.tail == this) {
                    // If the edge is the tail of the list, remove it
                    list.removeTail();
                }
                // Check if there any other lists that contain this edge
                for (Map.Entry<TreeNode, List<DoublyLinkedList<TreeEdge>>> entry : treeEdgeLists.entrySet()) {
                    List<DoublyLinkedList<TreeEdge>> lists = entry.getValue();
                    for (DoublyLinkedList<TreeEdge> list : lists) {
                        // If there is another list that contains this edge,
                        // remove this edge from that list too
                        if (list.contains(this)) {
                            list.remove(this);
                        }
