public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value.contains("${")) {
        // extract the variable name and its replacement value
        Pattern pattern = Pattern.compile("\\$\\{([a-zA-Z0-9_]+)\\}");
        Matcher matcher = pattern.matcher(value);
        if (matcher.find()) {
            String variable = matcher.group(1);
            String replacement = System.getProperty(variable, "");
            value = value.replace(matcher.group(0), replacement);
        }
    }
    return value;
}

public static String findAndSubst(String key, Properties props) {
    String value = null;

    // Check if key is null or empty
    if (key == null || key.isEmpty()) {
        throw new IllegalArgumentException("Key cannot be null or empty");
    }

    // Check if properties are null or empty
    if (props == null || props.isEmpty()) {
        throw new IllegalArgumentException("Properties cannot be null or empty");
    }

    // Find the value corresponding to the key in the properties
    value = (String) props.get(key);

    // If the value is null or empty, return an empty string
    if (value == null || value.isEmpty()) {
        return "";
    }

    // Perform variable substitution on the found value
    return variableSubstitution(value);
}

private static String variableSubstitution(String value) {
    Pattern pattern = Pattern.compile("\\$\\{([^{}]+?)\\}");
    Matcher matcher = pattern.matcher(value);
    StringBuffer buffer = new StringBuffer();

    while (matcher.find()) {
        String replacement = System.getenv(matcher.group(1));
        if (replacement != null) {
            matcher.appendReplacement(buffer, replacement);
        }
    }

    matcher.appendTail(buffer);
    return buffer.toString();
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("No value found for key: " + key);
    }
    return substituteVariables(value);
}

public static String substituteVariables(String value) {
    Pattern variablePattern = Pattern.compile("\\$\\{([a-zA-Z0-9\\-_]+)\\}");
    Matcher variableMatcher = variablePattern.matcher(value);
    StringBuffer buffer = new StringBuffer();
    while (variableMatcher.find()) {
        String varName = variableMatcher.group(1);
        String varValue = System.getProperty(varName);
        if (varValue == null) {
            throw new IllegalArgumentException("No system property found for variable: " + varName);
        }
        variableMatcher.appendReplacement(buffer, varValue);
    }
    variableMatcher.appendTail(buffer);
    return buffer.toString();
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("Key \"" + key + "\" not found");
    }
    return value.replaceAll("\\$\\{([A-Za-z0-9_]+)\\}", props::getProperty);
}

public static String findAndSubst(String key,Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    return value.replaceAll("\\$\\{([^\\}\\{]+)\\}", (match) -> props.getProperty(match.group(1)));
}

protected void appendDetail(StringBuffer buffer, String fieldName, int[] array) {
    // Check if the array is empty
    if (array.length == 0) {
        if (fieldName != null && fieldName.length() > 0) {
            buffer.append(fieldName);
        }
        buffer.append(" : ");
        buffer.append("[]");
        return;
    }

    // Append the field name and the opening bracket
    if (fieldName != null && fieldName.length() > 0) {
        buffer.append(fieldName);
    }
    buffer.append(" : [");

    // Append the first element
    buffer.append(array[0]);

    // Append the remaining elements
    for (int i = 1; i < array.length; i++) {
        buffer.append(", ");
        buffer.append(array[i]);
    }

    // Append the closing bracket
    buffer.append("]");
}

