	// Append the field name and opening bracket
	buffer.append(fieldName).append(": [");

	// Loop through the array elements and append each one to the string
	for (int i = 0; i < array.length; i++) {
		if (i > 0) {
			buffer.append(", ");
		}
		buffer.append(array[i]);
	}

	// Append the closing bracket
	buffer.append("]");
}

