private static long readRawVarint64(byte[] bytes, int startIndex) throws IOException {
    // Convert the first byte to an integer in the range [0, 128]
    int firstByte = Byte.toUnsignedInt(bytes[startIndex]);

    // If the byte is in the range [0, 127], this is a single-byte integer
    if (firstByte <= 127) {
        return firstByte;
    }

    // Otherwise, this is a multi-byte integer, so we need to read more bytes
    int bytesToRead = firstByte & 0x7F;
    int i = startIndex + 1;

    // Check if the bytes to read are valid
    if (bytesToRead + i > bytes.length) {
        throw new IOException("Invalid Varint length");
    }

    // Read the remaining bytes and combine them into a single integer
    long result = firstByte & 0x7F;
    for (int n = i; n < bytesToRead + i; n++) {
        result <<= 7;
        result |= bytes[n] & 0x7F;
    }

    // Return the result
    return result;
}

