    if (descriptor == null || descriptor.isEmpty()) {
      throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    if (descriptor.charAt(0) == '(' && descriptor.charAt(descriptor.length()-1) == ')') {
      int startIndex = 1;
      while (startIndex < descriptor.length() && descriptor.charAt(startIndex) != ')') {
        startIndex++;
      }
      pop(descriptor.substring(1, startIndex));
    } else if (descriptor.charAt(0) == 'L' && descriptor.charAt(descriptor.length()-1) == ';') {
      pop(descriptor.substring(1, descriptor.length()-1));
    } else {
      String[] types = descriptor.split(";");
      for (String type : types) {
        switch (type) {
          case "Ljava/lang/Integer;":
            outputFrameStack.pop();
            break;
          case "Ljava/lang/String;":
            outputFrameStack.pop();
            break;
          case "Ljava/lang/Object;":
            outputFrameStack.pop();
            break;
          default:
            throw new IllegalArgumentException("Descriptor contains an unsupported type: " + type);
        }
      }
    }
  }

private void pop(final String descriptor) {
    // Handle invalid input
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Pop abstract types from stack
    if (descriptor.startsWith("L")) {
        // Descriptor represents a class
        int closingBracketIndex = descriptor.lastIndexOf(";");
        if (closingBracketIndex == -1) {
            throw new IllegalArgumentException("Descriptor is not a valid class descriptor: " + descriptor);
        }

        String className = descriptor.substring(1, closingBracketIndex);
        pop(className);
    } else {
        // Descriptor represents a primitive type or void
        popPrimitiveOrVoid(descriptor);
    }
}

private void popPrimitiveOrVoid(final String descriptor) {
    // Handle invalid input
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Pop primitive or void type from stack
    switch (descriptor) {
        case "I":  // integer
            frameStack.pop();
            break;
        case "J":  // long
            frameStack.pop();
            break;
        case "F":  // float
            frameStack.pop();
            break;
        case "D":  // double
            frameStack.pop();
            break;
        case "Z":  // boolean
            frameStack.pop();
            break;
        case "C":  // char
            frameStack.pop();
            break;
        case "S":  // short
            frameStack.pop();
            break;
        case "B":  // byte
            frameStack.pop();
            break;
        case "V":  // void
            break;
        default:
            throw new IllegalArgumentException("Descriptor is not a valid primitive or void descriptor: " + descriptor);
    }
}

