Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    double width = box.getWidth();
    double height = box.getHeight();
    double halfWidth = width / 2.0;
    double halfHeight = height / 2.0;
    Box2D leftBox = new Box2D(box.getMinX(), box.getMaxY(), halfWidth, halfHeight);
    Box2D rightBox = new Box2D(box.getMinX() + halfWidth, box.getMaxY(), halfWidth, halfHeight);
    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Check if the box parameter is not null
    if (box == null) {
        throw new IllegalArgumentException("The box parameter cannot be null");
    }

    // Check if the box is not the null box
    if (box.isNull()) {
        throw new IllegalArgumentException("The box parameter cannot be the null box");
    }

    // Check if the box has a non-zero width
    if (box.width() <= 0) {
        throw new IllegalArgumentException("The box width cannot be zero or negative");
    }

    // Calculate the x coordinate of the middle of the box
    double xCoord = (box.left() + box.right()) / 2;

    // Get the width of the box
    double width = box.width();

    // Create two new boxes with the calculated coordinates and width
    Box2D leftBox = new Box2D(box.top(), xCoord, width / 2, box.height());
    Box2D rightBox = new Box2D(box.top(), xCoord + width / 2, width / 2, box.height());

    // Return the pair of boxes
    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    // Check if the given box is valid
    if (box == null || box.getWidth() == 0) {
        throw new IllegalArgumentException("Invalid box");
    }

    // Calculate the midpoint of the x-axis of the given box
    double midpoint = box.getMiddleX();

    // Create two new boxes from the given box, one with the left half of the area and the other with the right half
    Box2D leftBox = new Box2D(box.getMinX(), box.getMinY(), midpoint, box.getMaxY());
    Box2D rightBox = new Box2D(midpoint, box.getMinY(), box.getMaxX(), box.getMaxY());

    return new Pair<>(leftBox, rightBox);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    if (box.isEmpty()) {
        throw new IllegalArgumentException("Box cannot be empty");
    }

    double halfWidth = box.getWidth() / 2.0;
    double x1 = box.getXCenter() - halfWidth;
    double x2 = box.getXCenter() + halfWidth;
    double y1 = box.getYMin();
    double y2 = box.getYMax();

    Box2D box1 = new Box2D(x1, y1, x2, y2);
    Box2D box2 = new Box2D(x2, y1, x1, y2);

    return new Pair<Box2D, Box2D>(box1, box2);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double halfWidth = box.getWidth() / 2.0;
    Box2D box1 = new Box2D(box.getX(), box.getY(), halfWidth, box.getHeight());
    Box2D box2 = new Box2D(box.getX() + halfWidth, box.getY(), halfWidth, box.getHeight());
    return new Pair<>(box1, box2);
}

