private void enlarge(int size) {
    // Check if the byte vector already has enough capacity
    if (this.buffer.capacity() >= this.buffer.position() + size) {
        // The byte vector already has enough capacity, do nothing
        return;
    }

    // Calculate the new capacity that needs to be allocated
    int newCapacity = Math.max(this.buffer.capacity() * 2, this.buffer.position() + size);

    // Create a new byte array with the new capacity
    byte[] newBuffer = new byte[newCapacity];

    // Copy the existing data from the old byte array to the new byte array
    System.arraycopy(this.buffer, 0, newBuffer, 0, this.buffer.position());

    // Set the new byte array as the buffer for the byte vector
    this.buffer = newBuffer;
}

