public static string capitalize(string name)
{
    if (string.IsNullOrEmpty(name))
    {
        throw new ArgumentException("name must not be null or empty");
    }

    return char.ToUpper(name[0]) + name.Substring(1);
}

public static String capitalize(String name) {
    // 1. Handle null or empty input
    if (name == null || name.isEmpty()) {
        return name;
    }

    // 2. Split the input into words
    String[] words = name.split(" ");

    // 3. Capitalize the first letter of each word
    for (int i = 0; i < words.length; i++) {
        String lowercaseWord = words[i].toLowerCase();
        words[i] = lowercaseWord.substring(0, 1).toUpperCase() + lowercaseWord.substring(1);
    }

    // 4. Join the words back together
    String capitalizedName = String.join(" ", words);

    // 5. Return the capitalized name
    return capitalizedName;
}

