public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
   int totalSize = 0;
   while (node != null) {
      out.write(node.buffer, node.offset, node.length); // Write the current node to the output stream
      totalSize += node.length; // Add the current node's length to the total size
      node = node.next; // Move to the next node
   }
   return totalSize;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        out.write(node.getData());
        totalSize += node.getData().length;
        node = node.getNext();
    }
    return totalSize;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
        int contentSize = 0;
        while (node != null) {
            out.write(node.getData());
            contentSize += node.getLength();
            node = node.getNext();
        }
        return contentSize;
    }

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
        int totalSize = 0;
        while (node != null) {
            int size = node.size();
            out.writeInt(size);
            out.write(node.array(), 0, size);
            totalSize += size;
            node = node.next;
        }
        return totalSize;
    }

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int contentSize = 0;
    if (node.hasNext()) {
        contentSize += writeTo(out, node.next);
    }
    out.write(node.payload);
    contentSize += node.payload.length;
    return contentSize;
}

