private void addInitializedType(final int abstractType) {
    if (abstractType < 0 || abstractType >= graph.size()) {
        throw new IllegalArgumentException("Invalid type index");
    }
    if (initializedTypes.contains(abstractType)) {
        return;
    }
    initializedTypes.add(abstractType);
    for (int type : graph.successors(abstractType)) {
        addInitializedType(type);
    }
}

