private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        if (isAbstractType(currentFrame[i])) {
            stackMapTableEntries.add(new StackMapFrame(currentFrame[i].getElementType(), currentFrame[i].getSig()));
        }
    }
}

private void putAbstractTypes(int start, int end) {
        for (int i = start; i < end; i++) {
            if (currentFrame[i].isSimpleType()) {
                stackMapTableEntries.add(new StackMapTableEntry(currentFrame[i]));
            } else {
                switch (currentFrame[i].getType().getSort()) {
                    case Type.ARRAY:
                    case Type.OBJECT:
                        stackMapTableEntries.add(new StackMapTableEntry(currentFrame[i], VerificationTypeInfo.CONSTANT_CLASS, 0));
                        break;
                    case Type.METHOD:
                        stackMapTableEntries.add(new StackMapTableEntry(currentFrame[i], VerificationTypeInfo.CONSTANT_METHOD_HANDLE, 0));
                        break;
                    case Type.METHOD_TYPE:
                        stackMapTableEntries.add(new StackMapTableEntry(currentFrame[i], VerificationTypeInfo.CONSTANT_METHOD_TYPE, 0));
                        break;
                    case Type.WILDCARD:
                        stackMapTableEntries.add(new StackMapTableEntry(currentFrame[i], VerificationTypeInfo.CONSTANT_WILDCARD, 0));
                        break;
                    default:
