public static Character convertToType(final Class<?> type, final Object value) throws Exception {
    if (type != Character.class && type != char.class) {
      throw new IllegalArgumentException("Cannot convert value to type " + type + "; expected Character or char");
    }

    if (value == null) {
      return null;
    }

    if (value instanceof Character) {
      return (Character) value;
    }

    if (value instanceof String) {
      if (((String) value).length() == 1) {
        return ((String) value).charAt(0);
      }
      throw new IllegalArgumentException("Cannot convert string with more than one character to Character");
    }

    if (value instanceof Number && !(value instanceof Float) && !(value instanceof Double)) {
      return (char) ((Number) value).intValue();
    }

    throw new IllegalArgumentException("Cannot convert value " + value + " of type " + value.getClass() + " to Character");
  }

public Object convertToType(Class<?> type, Object value) throws Exception {
        if (type == Character.class || type == char.class) {
            if (value instanceof CharSequence) {
                if (((CharSequence) value).length() != 1) {
