private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    } else if (number == 2) {
        return true;
    } else if (number % 2 == 0) {
        return false;
    } else {
        for (int i = 3; i * i <= number; i += 2) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }
}

public static int nextPrime(int desiredCapacity) {
	if (desiredCapacity < 0) {
		throw new IllegalArgumentException("Illegal capacity: " + desiredCapacity);
	}
	if (desiredCapacity <= 1000) {
		// Find the prime number within 11% of desiredCapacity
		int prime = findPrime(desiredCapacity, 11);

		if (prime > 0) {
			return prime;
		}
	}

	// If desiredCapacity is greater than 1000, find the next prime number
	// starting from the first prime number greater than desiredCapacity
	int prime = findPrime(desiredCapacity+1);

	if (prime > 0) {
		return prime;
	}

	// If no prime number was found within the range, return the next prime number
	// greater than desiredCapacity.
	return desiredCapacity+1;
}

private static int findPrime(int desiredCapacity, int margin) {
	// Use a binary search to find the prime number within the margin of desiredCapacity.
	int low = (int)Math.ceil(desiredCapacity / (1-margin/100));
	int high = (int)Math.floor(desiredCapacity * (1+margin/100));

	while (low <= high) {
		int mid = (low + high) / 2;
		if (isPrime(mid)) {
			return mid;
		}
		low = mid+1;
	}

	return -1;
}

private static int findPrime(int num) {
	// Use a simple algorithm to find the next prime number starting from num.
	while (num > 0) {
		if (isPrime(num)) {
			return num;
		}
		num++;
	}

	return -1;
}

public static int nextPrime(int desiredCapacity) {
    int prime = findNextPrime(desiredCapacity);
    if (prime >= desiredCapacity && (prime - desiredCapacity) / desiredCapacity <= 0.11) {
        return prime;
    } else {
        throw new IllegalArgumentException("Could not find suitable prime number greater than or equal to " + desiredCapacity);
    }
}

private static int findNextPrime(int n) {
    if (n < 2) {
        return 2;
    } else if (n % 2 == 0) {
        return findNextPrime(n+1);
    } else {
        int flag = 1;
        for (int i = 3; i <= Math.sqrt(n); i += 2) {
            if (n % i == 0) {
                flag = 0;
                break;
            }
        }
        if (flag == 1) {
            return n;
        } else {
            return findNextPrime(n+2);
        }
    }
}

public static int nextPrime(int desiredCapacity) {
    // Edge case: desiredCapacity is less than 2
    if (desiredCapacity < 2) {
        return 2;
    }

    // Find the first prime number greater than or equal to the desired capacity
    int prime = desiredCapacity;
    while (!isPrime(prime)) {
        prime++;
    }

    // If the prime number is not within 11% of the desired capacity, return the next prime number within 11%
    if (prime - desiredCapacity > desiredCapacity * 0.11) {
        prime = nextPrime(prime + 1);
    }

    return prime;
}

private static boolean isPrime(int n) {
    // Handle edge cases: 0, 1, and negative numbers
    if (n <= 1) {
        return false;
    }

    // Check if the number is divisible by 2 to n-1
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

public int nextPrime(int desiredCapacity) {
    // Initialize a list to store prime numbers
    List<Integer> primeNumbers = new ArrayList<>();

    // Add 2, 3, and 5 to the list of prime numbers
    primeNumbers.add(2);
    primeNumbers.add(3);
    primeNumbers.add(5);

    // Iterate through the list of prime numbers and check if any of them
    // are greater than or equal to the desired capacity
    for (int primeNumber : primeNumbers) {
        if (primeNumber >= desiredCapacity) {
            return primeNumber;
        }
    }

    // If no prime number is greater than or equal to the desired capacity,
    // increase the desired capacity by 100 and repeat the process
    desiredCapacity += 100;
    return nextPrime(desiredCapacity);
}

