    if (!jsonObject.has("ats")) {
        content.put("ats", new ArrayList<>());
    } else {
        content.put("ats", jsonObject.getJsonArray("ats").stream()
                .map(obj -> {
                    JsonObject att = (JsonObject) obj;
                    return Helper.encodeURIComponent(att.getString("code")) + "=" + Helper.encodeURIComponent(att.getString("value"));
                })
                .collect(Collectors.toList()));
    }
    return content;
}

