    Map<String, Object> content = new HashMap<>();

    if (jsonObject.has("ats")) {
      content.put("ats", jsonObject.getAsJsonArray("ats").toArray());
    }

    return content;
  }

private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> content = new HashMap<>();
    JsonArray ats = jsonObject.getAsJsonArray("ats");
    if (ats != null) {
        for (JsonElement at : ats) {
            String atId = at.getAsString();
            String atName = getAtName(atId);
            content.put(atId, atName);
        }
    }
    return content;
}

