private static byte[] appendBytes(byte[] target, byte[] source) {
        byte[] result = new byte[target.length + source.length];
        System.arraycopy(target, 0, result, 0, target.length);
        System.arraycopy(source, 0, result, target.length, source.length);
        return result;
    }

public final byte[] toByteArray() {

  // initialize the output byte array
  byte[] outputArray = new byte[0];

  // append all the buffers to the output array
  for (ByteBuffer buffer : buffers) {
    byte[] bufferData = buffer.toByteArray();
    byte[] temp = new byte[outputArray.length + bufferData.length];
    System.arraycopy(outputArray, 0, temp, 0, outputArray.length);
    System.arraycopy(bufferData, 0, temp, outputArray.length, bufferData.length);
    outputArray = temp;
  }

  // return the output array
  return outputArray;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder unescapedStr = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            char nextC = str.charAt(i + 1);
            switch (nextC) {
                case 'n':
                    unescapedStr.append('\n');
                    i++;
                    break;
                case 'r':
                    unescapedStr.append('\r');
                    i++;
                    break;
                case 't':
                    unescapedStr.append('\t');
                    i++;
                    break;
                case '\\':
                    unescapedStr.append('\\');
                    i++;
                    break;
                case '\'':
                    unescapedStr.append('\'');
                    i++;
                    break;
                case '"':
                    unescapedStr.append('"');
                    i++;
                    break;
                case 'u':
                    if (i + 4 < len) {
                        char unicodeChar = (char) Integer.parseInt(str.substring(i + 2, i + 6), 16);
                        unescapedStr.append(unicodeChar);
                        i += 5;
                    } else {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
        } else {
            unescapedStr.append(c);
        }
    }
    return unescapedStr.toString();
}

