private static String javaCharset(String charset) {
  if (charset == null || charset.trim().isEmpty()) {
    throw new IllegalArgumentException("Charset name cannot be null or empty");
  }

  String[] javaCharsets = {
    "UTF-8", // Unicode utf-8
    "ISO_8859_1", // Latin Alphabet No. 1
    "US_ASCII", // Basic Latin
    "UTF-16", // Unicode utf-16
    "UTF-16BE", // Unicode utf-16 big endian
    "UTF-16LE", // Unicode utf-16 little endian
    "UTF-32", // Unicode utf-32
    "UTF-32BE", // Unicode utf-32 big endian
    "UTF-32LE" // Unicode utf-32 little endian
  };

  for (String javaCharset : javaCharsets) {
    if (javaCharset.equalsIgnoreCase(charset)) {
      return javaCharset;
    }
  }

  throw new IllegalArgumentException("Invalid charset name");
}

