public short readShort(final int offset) {
    // Use the input offset to calculate the position of the next byte to read
    int byteOffset = offset / 2;

    // Ensure that the byte offset is within the bounds of the class reader
    if (byteOffset < 0 || byteOffset >= numBytes) {
        throw new IndexOutOfBoundsException("The byte offset is outside the bounds of the class reader");
    }

    // Read the two bytes at the calculated offset
    byte[] bytes = read(byteOffset, 2);

    // Convert the two bytes to a short value
    return (short)((bytes[1] & 0xFF) << 8 | (bytes[0] & 0xFF));
}

public short readShort(final int offset) {
  if (offset < 0) {
    throw new IllegalArgumentException("Offset must be >= 0 but was " + offset);
  }
  int nextByte = readByte(offset);
  if (nextByte < 0) {
    nextByte = ((nextByte & 0x7F) * 2) + 1;
  }
  int nextByte2 = readByte(offset + 1);
  if (nextByte2 < 0) {
    nextByte2 = ((nextByte2 & 0x7F) * 2) + 1;
  }
  short ret = (short)((nextByte << 8) | (nextByte2 & 0xFF));
  if (ret < 0) {
    ret = (short)(Math.abs(ret * 2) + 1);
  }
  return ret;
}

public short readShort(final int offset) {
    if (offset < 0 || offset + 2 > classReader.Size) {
        throw new IndexOutOfBoundsException("Attempted to read out of bounds.");
    }
    // Read the desired bytes from the ClassReader
    byte[] bytes = new byte[2];
    for (int i = 0; i < 2; i++) {
        bytes[i] = classReader.bytesMap.Get((int)(offset + i));
    }
    // Convert the bytes to a short
    return (short)((bytes[0] & 0xff) << 8 | (bytes[1] & 0xff));
}

public short readShort(final int offset) {
    if (offset < 0 || offset >= buffer.length) {
        throw new IllegalArgumentException("Invalid offset: " + offset);
    }
    final int byte0 = buffer[offset] & 0xFF;
    final int byte1 = buffer[offset + 1] & 0xFF;
    final int result = (byte0 << 8) | byte1;
    if (result > Short.MAX_VALUE || result < Short.MIN_VALUE) {
        throw new IllegalStateException("Invalid short value: " + result);
    }
    return (short) result;
}

public short readShort(int offset) {
    if(classReader == null) {
        throw new NullPointerException("ClassReader is not initialized yet.");
    }
    short value = classReader.readShort(offset); 
    return value;
}

Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
    if (array == null) {
        return Array.newInstance(newArrayComponentType, 1);
    }

    int length = Array.getLength(array);
    Object newArray = Array.newInstance(array.getClass().getComponentType(), length + 1);
    System.arraycopy(array, 0, newArray, 0, length);

    return newArray;
}

public static Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
    Object newArray = Array.newInstance(newArrayComponentType, array.length + 1);
    System.arraycopy(array, 0, newArray, 0, array.length);
    return newArray;
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    if (array == null) {
        if (newArrayComponentType != null) {
            return Array.newInstance(newArrayComponentType, 1);
        } else {
            throw new NullPointerException("array and newArrayComponentType cannot both be null");
        }
    }
    final int length = Array.getLength(array);
    final Object copy = Array.newInstance(array.getClass().getComponentType(), length + 1);
    System.arraycopy(array, 0, copy, 0, length);
    return copy;
}

