    return newArray;
}

private static Object copyArrayGrow1(Object[] array, Class<?> newArrayComponentType) {
    // Check if the input array is null
    if (array == null) {
        // If so, create a new array with the specified component type and length 1
        return Array.newInstance(newArrayComponentType, 1);
    }

    // Create a new array with length 1 greater than the input array
    Object[] newArray = Array.newInstance(array.getClass().getComponentType(), array.length + 1);

    // Copy the elements of the input array into the new array
    System.arraycopy(array, 0, newArray, 0, array.length);

    // Set the last element of the new array to the default value
    newArray[newArray.length - 1] = null;

    // Return the new array
    return newArray;
}

private int computeBinaryLog(int n) {
    if (n > 0) {
        int log_value = 0;
        while (n > 1) {
            n >>= 1;
            log_value++;
        }
        return log_value + 1;
    } else {
        throw new IllegalArgumentException("Input must be positive");
    }
}

