private Set<V> intersection(Set<V> set1, Set<V> set2) {
    Set<V> result = new HashSet<>();
    for (V element : set1) {
        if (set2.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
  // handle edge case: if either set is null -> return empty set
  if (set1 == null || set2 == null) return new HashSet<>();

  // handle edge case: if either set is empty -> return empty set
  if (set1.isEmpty() || set2.isEmpty()) return new HashSet<>();

  // handle edge case: if either set contains null elements
  if (set1.contains(null) || set2.contains(null)) {
    Set<V> temp = new HashSet<>(set1);
    temp.remove(null);
    set1 = temp;
    temp = new HashSet<>(set2);
    temp.remove(null);
    set2 = temp;
  }

  // compute the intersection
  Set<V> intersection = new HashSet<>(set1);
  intersection.retainAll(set2);
  return intersection;
}

static String[] toNoNullStringArray(Collection<?> collection) {

    // Handle edge case: Null input
    if (collection == null) {
      throw new NullPointerException("Input collection cannot be null");
    }

    // Convert the collection to an array
    String[] array = new String[collection.size()];
    int i = 0;
    for (Object obj : collection) {
      if (obj != null) {
        array[i++] = obj.toString();
      }
    }

    // Return the new array
    return array;
  }

