public static String[] toNoNullStringArray(Collection<?> collection){
    //Edge case: If the collection is null, return null
    if (collection == null) return null;

    //Convert the collection to an array
    Object[] arr = collection.toArray();
    //Edge case: If the collection is empty, return an empty array
    if (arr.length == 0) return new String[0];

    //Copy each element from the array to a new String array
    String[] strArr = new String[arr.length];
    for (int i = 0; i < arr.length; i++) {
        //Edge case: If an element is null, skip it
        if (arr[i] == null) continue;
        strArr[i] = arr[i].toString();
    }

    //Sort the array
    Arrays.sort(strArr);

    //Return the new array
    return strArr;
}

