public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }
    if (charBuffer == null || charBuffer.length < 0) {
        throw new IllegalArgumentException("Invalid char buffer");
    }
    ConstantPoolEntry constantPoolEntry = classFileBuffer[constantPoolEntryIndex];
    if (constantPoolEntry.tag != Tag.UTF8.tag) {
        throw new IllegalArgumentException("Invalid constant pool entry type");
    }
    Utf8Info utf8Info = (Utf8Info) constantPoolEntry;
    int length = utf8Info.length;
    if (length > charBuffer.length) {
        throw new IllegalArgumentException("Char buffer too small");
    }
    System.arraycopy(utf8Info.bytes, 0, charBuffer, 0, length);
    return new String(charBuffer, 0, length);
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
  if (constantPoolEntryIndex >= 0 && constantPoolEntryIndex < classFileBuffer.length) {
    final int tag = classFileBuffer[constantPoolEntryIndex] & 0xff;
    if (tag != CONSTANT_Utf8) {
      throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }
    final int length = classFileBuffer[constantPoolEntryIndex + 1] & 0xffff;
    if (length > charBuffer.length) {
      throw new IllegalArgumentException("Char buffer is not large enough to read the string");
    }
    final int charOffset = constantPoolEntryIndex + 3;
    for (int i = 0; i < length; i++) {
      charBuffer[i] = (char) (classFileBuffer[charOffset + i] & 0xff);
    }
    return new String(charBuffer, 0, length);
  } else {
    throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
  }
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Check that the constant pool entry index is valid
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= constantPoolCount) {
        throw new IndexOutOfBoundsException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    // Check that the char buffer is large enough
    if (charBuffer.length < constantUtf8Size[constantPoolEntryIndex]) {
        throw new IllegalArgumentException("The char buffer is too small to store the constant utf8 string: " + charBuffer.length);
    }

    // Read the constant utf8 string
    int offset = utfOffset[constantPoolEntryIndex]; // utfOffset is a global array
    int length = utfCount[constantPoolEntryIndex]; // utfCount is a global array
    System.arraycopy(classFileBuffer, offset, charBuffer, 0, length);

    // Return the constant utf8 string as a String object
    return new String(charBuffer, 0, length);
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
  if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
    throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
  }

  // Read the tag and length of the CONSTANT_UTF8 entry
  final int tag = readUnsignedShort();
  final int length = readUnsignedShort();

  if (tag != CONSTANT_UTF8) {
    throw new IllegalArgumentException("Invalid constant pool entry type: " + tag);
  }

  if (length < 1) {
    throw new IllegalArgumentException("Invalid string length: " + length);
  }

  // Read the string data
  for (int i = 0; i < length; i++) {
    charBuffer[i] = (char) readUnsignedByte();
  }

  return new String(charBuffer, 0, length);
}

