public static long factorial(int n) {
  // Step 1: Handle invalid inputs by returning 0 for any negative or zero inputs
  if (n <= 0) {
    return 0;
  }

  // Step 2: Initialize the result to 1
  long result = 1;

  // Step 3: Iterate from 1 to the input number and multiply the result accordingly
  for (int i = 1; i <= n; i++) {
    result *= i;
  }

  // Step 4: Return the result
  return result;
}

