public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null && byteLength > 0) {
        throw new NullPointerException("byteArrayValue cannot be null if byteLength is > 0");
    }

    if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Invalid offset and length values");
    }

    if (this.byteVector.length - this.byteVector.position + byteLength > this.byteVector.capacity) {
        growByteVector(byteLength);
    }

    System.arraycopy(byteArrayValue, byteOffset, this.byteVector, this.byteVector.position, byteLength);
    this.byteVector.position += byteLength;

    return this;
}

private void growByteVector(int requiredCapacity) {
    int newCapacity = this.byteVector.capacity * 2;
    while (newCapacity < this.byteVector.position + requiredCapacity) {
        newCapacity *= 2;
    }

    ByteVector newByteVector = new ByteVector(newCapacity);
    System.arraycopy(this.byteVector.array, 0, newByteVector.array, 0, this.byteVector.position);
    this.byteVector = newByteVector;
}

