public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Check if the input parameters are valid
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength cannot be negative");
    }
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset must be non-negative and less than byteArrayValue.length");
    }
    if (byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset + byteLength must be less than or equal to byteArrayValue.length");
    }

    // Ensure the byte vector is large enough to hold the supplied data
    if (byteLength > capacity) {
        grow(byteLength);
    }

    // Copy the data from the input byte array to this byte vector
    System.arraycopy(byteArrayValue, byteOffset, this.data, this.offset, byteLength);

    // Update the offset and size of this byte vector
    this.size += byteLength;
    this.offset += byteLength;

    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        throw new IllegalArgumentException("byteArrayValue cannot be null");
    }

    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Invalid byte offset");
    }

    if (byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Invalid byte length");
    }

    ensureCapacity(byteLength);

    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
        internalBuffer[byteCursor++] = byteArrayValue[i];
    }

    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Check if byteLength is larger than 0
    if (byteLength <= 0) {
        throw new IllegalArgumentException("byteLength must be positive");
    }

    // Check if byteArrayValue is not null
    if (byteArrayValue == null) {
        throw new NullPointerException("byteArrayValue cannot be null");
    }

    // Check if byteOffset is valid
    if (byteOffset > byteArrayValue.length - byteLength) {
        throw new IndexOutOfBoundsException("byteOffset is beyond the range of byteArrayValue");
    }

    // Check if enlarging the vector is necessary
    if (this.length < byteLength) {
        enlargeVector(byteLength - this.length);
    }

    System.arraycopy(byteArrayValue, byteOffset, this.bytes, this.length, byteLength);
    this.length += byteLength;
    return this;
}

