        char c = input.charAt(i);
        if (c == '\\' && input.length() > i + 1) {
            char nextChar = input.charAt(i + 1);
            if (nextChar == '\\') {
                output.append('\\');
                i++;
            } else if (nextChar == 'n') {
                output.append('\n');
                i++;
            } else if (nextChar == 'r') {
                output.append('\r');
                i++;
            } else if (nextChar == 't') {
                output.append('\t');
                i++;
            } else {
                output.append(c);
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

