}

private String unescapeId(String input) {
  // 1. A DOT identifier can contain the characters a-zA-Z0-9_
  // 2. A DOT identifier must start with a-zA-Z
  // 3. A DOT identifier cannot start with a number
  // 4. A DOT identifier cannot contain special characters
  // 5. An underscore at the beginning or end of the identifier is not allowed

  // Check if input is null or empty
  if (input == null || input.length == 0) {
    return input;
  }

  // Check if the first character is a letter
  if (!Character.isLetter(input.charAt(0))) {
    throw new IllegalArgumentException("Invalid input: first character must be a letter");
  }

  // Check if the input contains any special characters
  for (int i = 0; i < input.length(); i++) {
    if (!Character.isLetterOrDigit(input.charAt(i)) && input.charAt(i) != '_') {
      throw new IllegalArgumentException("Invalid input: contains special characters");
    }
  }

  // Check if the input starts or ends with an underscore
  if (input.endsWith("_") || input.startsWith("_")) {
    throw new IllegalArgumentException("Invalid input: cannot start or end with an underscore");
  }

  return input;
}

