    Set<Integer> minBucket = bucketsByLabel.get(minLabel);

    // Move all vertices in the minimum bucket to bucket 0
    bucketsByLabel.get(0).addAll(minBucket);

    // Clear the minimum bucket
    minBucket.clear();

