private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
  // Initialize a new empty bucket for non-overlapping vertices
  bucketsByLabel.add(new HashSet<Integer>());
  // Iterate over all vertices
  for (int i = 0; i < labels.size(); i++) {
    int label = labels[i];
    if (label > minLabel) {
      // Move non-overlapping vertices to new bucket
      bucketsByLabel[label].add(i);
    } else if (label == minLabel) {
      // Clear minimum label bucket and update corresponding vertex
      bucketsByLabel[label].clear();
      labels[i] = 0;
    }
  }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Check if the input is valid
    if (bucketsByLabel == null || labels == null || minLabel < 0) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Find the bucket with the minimum label
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()) {
        throw new IllegalArgumentException("Bucket with minimum label does not exist");
    }

    // Move all vertices from the minimum bucket to the first bucket
    for (Integer vertex : minBucket) {
        bucketsByLabel.get(0).add(vertex);
    }

    // Remove all vertices from the minimum bucket and update labeling
    bucketsByLabel.get(minLabel).clear();
    for (int i = minLabel + 1; i < bucketsByLabel.size(); i++) {
        if (bucketsByLabel.get(i) != null) {
            for (Integer vertex : bucketsByLabel.get(i)) {
                labels.set(vertex, i - 1);
            }
        }
    }

    // Update labeling for all vertices in the minimum bucket
    for (Integer vertex : minBucket) {
        labels.set(vertex, 0);
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    for (int vertex : bucketsByLabel.get(minLabel)) {
        bucketsByLabel.get(0).add(vertex);
        bucketsByLabel.get(minLabel).remove(vertex);
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.get(minLabel).clear();

    // Update the labeling
    labels.set(minLabel, 0);
}

