    if (node == null) {
        throw new NullPointerException("node cannot be null");
    }
    ListNodeImpl<E> previousNode = node.previous;
    ListNodeImpl<E> nextNode = node.next;

    // Special case: node is the first node
    if (previousNode == null) {
        if (nextNode == null) {
            // The list is empty
            return false;
        } else {
            // The node is the first node in the list
            // Update the first node reference
            firstNode = nextNode;
        }
    } else {
        // Node is an internal node
        // Update the previous node's next reference
        previousNode.next = nextNode;
    }

    // Special case: node is the last node
    if (nextNode == null) {
        // The node is the last node in the list
        // Update the last node reference
        lastNode = previousNode;
    } else {
        // Node is an internal node
        // Update the next node's previous reference
        nextNode.previous = previousNode;
    }
    return true;
}

for (ListNodeImpl<E> current = head; current != null; current = current.next) {
