private boolean unlink(ListNodeImpl<E> node) {
        if (node == null || node.next == null) return false; // edge case: null node or node is already the last node
        // get reference to the previous node
        ListNodeImpl<E> prev = this.head;
        while (prev != null && prev.next != node) prev = prev.next;
        if (prev == null) return false; // edge case: node is not in the list
        // unlink the node from the list
        prev.next = node.next;
        node.next = null;
        return true;
}

public List<SequenceRange> buildSequenceRanges() {
        List<SequenceRange> sequenceRanges = new ArrayList<>();

        // Check if list is empty
        if (sequenceRanges.isEmpty()) {
            System.out.println("Input list cannot be empty");
            return sequenceRanges;
        }

        // Check if all elements in the list are valid
        for (SequenceRange sequenceRange : sequenceRanges) {
            if (sequenceRange == null || sequenceRange.getStart() < 0 || sequenceRange.getStart() > sequenceRange.getEnd()) {
                System.out.println("Invalid input: sequenceRange cannot be null, start must be greater than or equal to 0, and end must be greater than start");
                return sequenceRanges;
            }
        }

        // If all inputs are valid, build sequence ranges
        for (int i = 1; i <= sequenceRanges.size(); i++) {
            sequenceRanges.add(new SequenceRange(sequenceRanges.get(i - 1).getEnd() + 1, sequenceRanges.get(i).getStart() - 1));
        }

        return sequenceRanges;
    }

