public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> rangeList = new ArrayList<>();

    for (int i = 0; i < sequenceSegments.size(); i++) {
        SequenceSegment segment = sequenceSegments.get(i);
        List<SequenceRange> segmentRanges = segment.getRanges();

        // Add the first range of the segment to the range list
        if (i == 0) {
            rangeList.add(segmentRanges.get(0));
        }

        // Add the last range of the current segment to the range list
        // Only if the segment has more than one range
        if (segmentRanges.size() > 1) {
            rangeList.add(segmentRanges.get(segmentRanges.size() - 1));
        }

        // Add all ranges of the subsequent segments without the last range
        // Only if the segment has more than one range
        if (segmentRanges.size() > 1 && i < sequenceSegments.size() - 1) {
            rangeList.addAll(segmentRanges.subList(1, segmentRanges.size() - 1));
        }
    }

    return rangeList;
}

