public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array cannot be null");
    }
    if (from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
        throw new IndexOutOfBoundsException("from and to indices must be non-negative and within the bounds of the array");
    }
    if (from > to) {
        throw new IllegalArgumentException("from index must be less than or equal to to index");
    }

    int mid = (from + to) / 2;
    for (int i = 0; i < mid; i++) {
        V temp = arr[from + i];
        arr[from + i] = arr[to - i];
        arr[to - i] = temp;
    }
}

