  String str = loggingEvent.toLowerCase().trim();
  if (str.matches("[a-z0-9]+")) {
    // String contains only letters, numbers and spaces
    retVal = Filter.ACCEPT;
  } else if (str.matches("[&-+*/]{1,}") || str.matches("[^\\w #&+-*/%,()\\s]")) {
    // String contains special characters
    retVal = Filter.DENY;
