public static String base64Decode(final String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    byte[] byteArr = s.getBytes();
    int length = byteArr.length;
    List<Integer> values = new ArrayList<>();
    for (int i = 0; i < length; i += 4) {
        int val = 0;
        for (int j = i; j < i + 4; j++) {
            int shift = (3 - (j - i)) * 6; // compute the shift needed
            if (j < length) {
                val += ((byteArr[j] - ' ') & 0x3f) << shift; // get the 6 bits representing base64 char and add to value
            }
        }
        values.add(val);
    }

    String decoded = new BigInteger(values.stream().mapToInt(v -> v).toArray()).toString(36);
    return decoded.toUpperCase();
}

