    }

    // Step 2: Convert the input string to a byte array using the Base64 decoder
    byte[] inputBytes = Base64.getDecoder().decode(s);

    // Step 3: Convert the byte array to a string using the UTF-8 character set
    String decodedString = new String(inputBytes, StandardCharsets.UTF_8);

    // Step 4: Return the decoded string
    return decodedString;
}

public static String base64Decode(String s) {
    // Check for null or empty string
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Create a new StringBuffer to hold the decoded string
    StringBuffer decoded = new StringBuffer();

    // Convert the string to a char array
    char[] chars = s.toCharArray();

    // Base64 decoding algorithm
    for (int i = 0; i < chars.length; i += 4) {
        // Check if the string has enough characters left for a valid group of 4 characters
        if (i + 4 > chars.length) {
            throw new IllegalArgumentException("Invalid input");
        }

        // Decode the first character of the group
        int firstChar = getBase64Value(chars[i]);
        int secondChar = getBase64Value(chars[i + 1]);
        int thirdChar = getBase64Value(chars[i + 2]);
        int fourthChar = getBase64Value(chars[i + 3]);

        // Calculate the first byte of the group
        int byteOne = ((firstChar & 0b111111) << 2) | (secondChar >> 4);
        decoded.append((char) byteOne);

        // Calculate the second byte of the group
        int byteTwo = ((secondChar & 0b1111) << 4) | (thirdChar >> 2);
        decoded.append((char) byteTwo);

        // Calculate the third byte of the group
        int byteThree = ((thirdChar & 0b11) << 6) | fourthChar;
        decoded.append((char) byteThree);
    }

    // Return the decoded string
    return decoded.toString();
}

