private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();
    for (E edge : graph.edges()) {
        List<Pair<Integer, Integer>> separators = new ArrayList<>();
        for (V endpoint : edge.endpoints()) {
            for (E e1 : graph.edges(endpoint)) {
                if (e1 != edge && graph.adjacent(e1.from(), e1.to()) && e1.weight() < edge.weight()) {
                    separators.add(new Pair<>(endpoint, e1));
                }
            }
        }
        separatorList.add(new Pair<>(separators, edge));
    }
    return separatorList;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();
    for (E edge : graph.getEdges()) {
        List<Pair<Integer, Integer>> separator = new ArrayList<>();
        for (V vertex : graph.neighbors(edge.getSource())) {
            if (!vertex.equals(edge.getTarget())) {
                List<Pair<Integer, Integer>> localSeparator = new ArrayList<>();
                localSeparator.add(new Pair<>(vertex, edge));
                separator.addAll(localSeparator);
            }
        }
        separatorList.add(new Pair<>(separator, edge));
    }
    return separatorList;
}

private List<Pair<List<Pair<Integer, Integer>>>> computeGlobalSeparatorList() {
    // Initialize the result list
    List<Pair<List<Pair<Integer, Integer>>>> result = new ArrayList<>();

    // Iterate over all vertices in the graph
    for (int i = 0; i < V; i++) {
      // Iterate over all edges incident to the current vertex
      for (int j = 0; j < deg[i]; j++) {
        // Compute the separator list for the current edge
        List<Pair<Integer, Integer>> separatorList = computeSeparatorList(i, j);

        // Add the separator list to the result list for the current edge
        result.add(separatorList);
      }
    }

    return result;
  }

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();
    for (int i = 0; i < graph.size(); i++) {
        for (int j = 0; j < graph.size(); j++) {
            if (i != j && graph.get(i).contains(Tuple(j, graph.get(j).getWeight())) && graph.get(j).contains(Tuple(i, graph.get(i).getWeight()))) {
                List<Pair<Integer, Integer>> neighbors = graph.get(i).getNeighbors(j);
                List<Pair<Integer, Integer>> separators = new ArrayList<>();
                for (Pair<Integer, Integer> neighbor : neighbors) {
                    if (!separators.contains(Tuple(i, neighbor.getFirst())) && !separators.contains(Tuple(neighbor.getFirst(), j))) {
                        separators.add(Tuple(i, neighbor.getFirst()));
                    }
                }
                separatorList.add(Pair(separators, graph.get(i).getWeight()));
            }
        }
    }
    return separatorList;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
        List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();

        for (E e : graph.getEdges()) {
            List<Pair<Integer, Integer>> minimumSeparator = computeMinimumSeparator(e);
            separatorList.add(new Pair(minimumSeparator, e));
        }

        return separatorList;
    }

private List<Pair<Integer, Integer>> computeMinimumSeparator(E edge) {
        List<Pair<Integer, Integer>> minimumSeparator = new ArrayList<>();

        for (E e : graph.getEdges()) {
            if (isPartOfMinimumSeparator(edge, e)) {
                minimumSeparator.add(new Pair(e.getSource(), e.getTarget()));
            }
        }

        return minimumSeparator;
    }

private boolean isPartOfMinimumSeparator(E edge1, E edge2) {
        // Check if edge2 is in the neighborhood of edge1
        if (!graph.getNeighbors(edge1.getDestination()).contains(edge2.getDestination())) {
            return false;
        }

        // Check if edge1 and edge2 are connected in the subgraph
        if (!graph.areConnected(edge1.getSource(), edge2.getSource())) {
            return false;
        }

        return true;
    }

