public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Invalid row index: " + row);
    }
    if (table.getParent() != pane) {
        throw new IllegalArgumentException("JTable does not belong to the specified JScrollPane");
    }
    // Select the specified row in the table
    table.setRowSelectionInterval(row, row);
    // Scroll the pane to show the selected row
    pane.getViewport().setViewPosition(new Point(0, 0));
    pane.repaint();
}

private static void selectRow(int row, JTable table, JScrollPane pane) {
  // Check if the specified row is within the bounds of the JTable
  if (row >= 0 && row < table.getRowCount()) {
    // Get the selected row in the JTable
    int selectedRow = table.getSelectedRow();
    // Check if the specified row is already selected
    if (selectedRow != row) {
      // Set the new selected row in the JTable
      table.setRowSelectionInterval(row, row);
      // Get the height of the specified row in the JTable
      int rowHeight = table.getRowHeight(row);
      // Set the VerticalUnit for the JScrollBar
      switch (table.getScrollPaneVerticalUnit()) {
        case LINE:
          pane.getVerticalScrollBar().setUnitIncrement(rowHeight);
          break;
        case PIXEL:
          pane.getVerticalScrollBar().setUnitIncrement(rowHeight);
          break;
        case INCH:
          pane.getVerticalScrollBar().setUnitIncrementInch((double) rowHeight / 72);
          break;
      }
      // Repeat the vertical unit for the JScrollBar
      pane.getVerticalScrollBar().setUnitIncrementRepeat(Math.max(pane.getVerticalScrollBar().getUnitIncrement(), 1));
      // Scroll the JScrollPane to the newly selected row
      pane.getVerticalScrollBar().setValue(rowHeight * (row - selectedRow));
    }
    // Delay the repaint() call to give enough time for the JTable to paint the selected row
    pane.getVerticalScrollBar().repaint(30);
  }
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Delay the repaint call to give the table time to properly paint the newly selected row
    SwingUtilities.invokeLater(() -> {
        table.setRowSelectionInterval(row, row);
        pane.getViewport().setViewPosition(new Point(0, row * table.getRowHeight()));
        pane.repaint();
    });
}

