public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Check if the row index is valid
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Invalid row index: " + row);
    }

    // Select the row in the table
    table.setRowSelectionInterval(row, row);

    // Scroll the pane to show the newly selected row
    if (!pane.getViewport().getViewRect().intersects(table.getRowBounds(row))) {
        pane.getViewport().setViewPosition(new Point(0, (row - 1) * table.getRowHeight()));
    }

    // Delay the repaint() call to ensure that the table is properly painted
    // before returning from this method
    try {
        Thread.sleep(200);
    } catch (InterruptedException e) {
        // Handle interruption error
    }

    // Repaint the table to ensure that the selected row is visible
    table.repaint();
}

