public static Type resolveBound(TypeVariable<?> typeVariable) {
        // Use a nested loop to iterate through all the bounds of the type variable
        for (Type bound : typeVariable.getBounds()) {
            // If the bound is not a wildcard type, return it
            if (!(bound instanceof WildcardType)) {
                return bound;
            }

            // If the bound is a wildcard type, check if it has an upper bound
            WildcardType wildcard = (WildcardType) bound;
            Type[] upperBounds = wildcard.getUpperBounds();
            if (upperBounds.length > 0) {
                // If there is an upper bound, return it
                return upperBounds[0];
            }
        }

        // If none of the bounds can be resolved, return Unknown.class
        return Unknown.class;
    }

