        }
    }
}

private void pop(final String descriptor) {
    // Make sure the descriptor is not null
    if (descriptor == null) {
        throw new NullPointerException("Descriptor cannot be null");
    }

    // Check if the descriptor is for a primitive type
    if (descriptor.startsWith("I") || descriptor.startsWith("J") || descriptor.startsWith("S") || descriptor.startsWith("B") || descriptor.startsWith("C") || descriptor.startsWith("D") || descriptor.startsWith("F") || descriptor.startsWith("V")) {
        // Pop a primitive value from the stack
        pop();
    } else if (descriptor.startsWith("[")) {
        // Pop an array from the stack
        popArray();
    } else if (descriptor.startsWith("L")) {
        // Pop an object from the stack
        popObject();
    } else {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

private void pop() {
    // Check if the stack is empty
    if (stack.isEmpty()) {
        throw new IllegalStateException("Cannot pop from an empty stack");
    }

    // Pop a primitive value from the stack
    stack.pop();
}

private void popArray() {
    // Check if the stack is empty
    if (stack.isEmpty()) {
        throw new IllegalStateException("Cannot pop from an empty stack");
    }

    // Pop an array from the stack
    stack.pop();
}

private void popObject() {
    // Check if the stack is empty
    if (stack.isEmpty()) {
        throw new IllegalStateException("Cannot pop from an empty stack");
    }

    // Pop an object from the stack
    stack.pop();
}

