public static String applyRelativePath(String path, String relativePath) {
  // Check if the input is valid
  if (path == null || relativePath == null) {
    throw new IllegalArgumentException("path or relativePath is null");
  }

  // Split the path and relative path into arrays of their components
  String[] pathComponents = path.split("/");
  String[] relativePathComponents = relativePath.split("/");

  // Check if the relative path is actually a relative path
  if (relativePathComponents.length == 0 || relativePathComponents[0].isEmpty()) {
    throw new IllegalArgumentException("relativePath is not a valid relative path");
  }

  // Remove the first component of the relative path if it is "." or ".."
  if (relativePathComponents[0].equals(".")) {
    relativePathComponents = Arrays.copyOfRange(relativePathComponents, 1, relativePathComponents.length);
  } else if (relativePathComponents[0].equals("..")) {
    relativePathComponents = Arrays.copyOfRange(relativePathComponents, 2, relativePathComponents.length);
  }

  // Check if the relative path is still a valid relative path
  if (relativePathComponents.length == 0) {
    throw new IllegalArgumentException("relativePath is not a valid relative path");
  }

  // Join the path and relative path components
  String[] newPathComponents = new String[pathComponents.length + relativePathComponents.length];
  System.arraycopy(pathComponents, 0, newPathComponents, 0, pathComponents.length);
  System.arraycopy(relativePathComponents, 0, newPathComponents, pathComponents.length, relativePathComponents.length);

  // Return the new path
  return String.join("/", newPathComponents);
}

