        // if character is in ASCII range 0-31
        switch (ch) {
            case '\u0000': return "\u0000";
            case '\u0001': return "\u0001";
            case '\u0002': return "\u0002";
            // ...
            case '\ufffe': return "\ufffe";
            case '\uffff': return "\uffff";
