public static String toString(final char ch) {
    // Handle edge case where ch is a whitespace character
    if (Character.isWhitespace(ch)) {
        return String.valueOf(ch);
    }

    // Handle edge case where ch is out of the bound of the cache
    if (ch < Character.MIN_VALUE || ch > Character.MAX_VALUE) {
        throw new IllegalArgumentException("Invalid character: " + ch);
    }

    // Handle edge case where ch is an ASCII 7 bit character
    if (ch <= 0x7F) {
        return ASCII_7_BIT_CACHE[ch];
    }

    // Handle all other cases
    return String.valueOf(ch);
}

